using Rampage.ExceptionExtensions;
using Rampage.Reflection;
using Rampage.Utilities;
using System;
using System.Collections;
using System.Net;
using System.Reflection;
using System.Threading.Tasks;

namespace Rampage.Net
{
    /// <summary>
    /// 声明式 HTTP 客户端基类：DynamicHttpClientBuilder 生成的实现类（“接口名+Implementation”）继承本类；
    /// 接口方法参数由 IL 打包为字典后调用 <see cref="CallAsync{T}"/>，由本类完成参数特性解析、请求组装与响应转换。
    /// Base class of declarative HTTP clients: implementations generated by DynamicHttpClientBuilder ("interface-name+Implementation") derive from it;
    /// interface method arguments are packed into a dictionary by emitted IL and dispatched to <see cref="CallAsync{T}"/>, which resolves parameter attributes, builds the request and converts the response.
    /// </summary>
    public abstract class SuperHttpClient : ISuperHttpClient
    {
        /// <summary>异常键：[RequestFormFile] 参数仅允许用于 POST 请求 / Exception key: a [RequestFormFile] parameter is only allowed on POST requests</summary>
        public const string EX_KEY_RequestFormFileAttribute_Parameter_Not_Allowed = "RequestFormFileAttribute_Parameter_Not_Allowed";
        /// <summary>异常键：[RequestFormFile] 与 [RequestBody] 参数不允许同时使用 / Exception key: [RequestFormFile] and [RequestBody] parameters cannot be combined</summary>
        public const string EX_KEY_RequestBodyAttribute_Parameter_Not_Allowed = "RequestBodyAttribute_Parameter_Not_Allowed";
        /// <summary>异常键：[RequestFormFile] 参数值必须为 byte[] 或 Stream / Exception key: a [RequestFormFile] parameter value must be byte[] or Stream</summary>
        public const string EX_KEY_Invalid_RequestFormFileAttribute_Parameter_Value = "Invalid_RequestFormFileAttribute_Parameter_Value";


        /// <summary>默认构造函数 / Default constructor</summary>
        public SuperHttpClient()
        {
        }

        /// <summary>
        /// 依据 <see cref="ClientAttribute"/> 延迟加载客户端配置项、ApiRoot 与拦截器实例
        /// Lazily loads the client config entry, ApiRoot and interceptor instance based on <see cref="ClientAttribute"/>
        /// </summary>
        /// <remarks>
        /// 仅当 <see cref="ClientAttribute"/> 非空时执行，且各配置项只在尚未赋值时填充（可被提前设置的值覆盖）：
        /// 配置名默认取实现类类型名（动态生成类为“接口名+Implementation”，如需对齐配置节请显式设置特性 Name）；
        /// ApiRoot 优先级：已设置值 &gt; 特性 Root &gt; 配置项 Root；拦截器由特性 Handler 指定的类型经 EmitTool 实例化。
        /// Runs only when <see cref="ClientAttribute"/> is set, and fills each item only if not already assigned (pre-set values win):
        /// the config name defaults to the implementation type name ("interface-name+Implementation" for generated classes — set the attribute's Name explicitly to match the config section);
        /// ApiRoot priority: existing value &gt; attribute Root &gt; config Root; the interceptor is instantiated via EmitTool from the type given by the attribute's Handler.
        /// </remarks>
        public virtual void TryLoadConfig()
        {
            if (ClientAttribute == null)
            {
                return;
            }

            string? name = ClientAttribute.Name;
            if (string.IsNullOrWhiteSpace(name))
            {
                Type clientType = this.GetType();
                name = clientType.Name;
            }
            if (Config == null)
            {
                Config = SuperClientConfigManager.GetConfig(name);
            }

            if (string.IsNullOrEmpty(ApiRoot))
            {
                string? root = ClientAttribute.Root;
                if (!string.IsNullOrWhiteSpace(root))
                {
                    ApiRoot = root;
                }
                else if (Config != null)
                {
                    ApiRoot = Config.Root!;
                }
            }

            if (Interceptor == null)
            {
                Type? handlerType = ClientAttribute.Handler;
                if (handlerType != null)
                {
                    object? handlerObj = EmitTool.CreateModel(handlerType);
                    if (handlerObj != null)
                    {
                        Interceptor = handlerObj as ISuperClientInterceptor;
                    }
                }
            }
        }

        /// <summary>接口上标注的 [SuperClient] 特性（由 <see cref="CallAsync{T}"/> 调用时自动设置）/ The [SuperClient] attribute applied to the client interface (set automatically when <see cref="CallAsync{T}"/> is invoked)</summary>
        public virtual SuperClientAttribute? ClientAttribute
        {
            get;
            set;
        }

        /// <summary>从配置节 SuperHttpClients:Clients 按名加载的客户端配置项 / The client config entry loaded by name from the SuperHttpClients:Clients section</summary>
        public virtual SuperClientConfig? Config
        {
            get;
            protected set;
        }

        /// <summary>API 根地址（scheme + host[:port]），用于拼接完整请求地址与选择共享 HttpClient / The API root (scheme + host[:port]) used to build full request URLs and pick the shared HttpClient</summary>
        public virtual string? ApiRoot
        {
            get;
            protected set;
        }

        /// <summary>请求/响应拦截器 / The request/response interceptor</summary>
        public virtual ISuperClientInterceptor? Interceptor
        {
            get;
            set;
        }

        /// <summary>将资源路径与 ApiRoot 拼接为完整请求地址 / Combines the resource path with ApiRoot into a full request URL</summary>
        /// <param name="resource">资源路径 / The resource path</param>
        /// <returns>拼接后的完整 URL / The combined full URL</returns>
        public virtual string GetApiUrl(string resource)
        {
            return PathTool.CombileUrl(ApiRoot!, resource);
        }

        /// <summary>发送 HTTP 请求并得到响应报文（按 ApiRoot 选择共享客户端）/ Sends an HTTP request and returns the response message (shared client chosen by ApiRoot)</summary>
        /// <param name="resource">资源路径（与 ApiRoot 拼接）/ The resource path (combined with ApiRoot)</param>
        /// <param name="options">请求选项 / The request options</param>
        /// <returns>响应报文任务 / A task returning the response message</returns>
        public virtual Task<HttpResponseMessage?> RequestMessageAsync(string resource, SuperRequestOptions? options = null)
        {
            HttpClient client = SuperClientUtility.GetClient(ApiRoot!);
            string url = GetApiUrl(resource);
            return client.RequestMessageAsync(url, options);
        }

